CREATE TABLE notifications(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,user_id BINARY(16),idempotency_key VARCHAR(64) NOT NULL UNIQUE,channel VARCHAR(20) NOT NULL,recipient VARCHAR(254) NOT NULL,subject VARCHAR(200),body TEXT NOT NULL,template_key VARCHAR(100),status VARCHAR(20) NOT NULL,attempt_count INTEGER NOT NULL,max_attempts INTEGER NOT NULL,provider_message_id VARCHAR(150),last_error VARCHAR(1000),created_at TIMESTAMP(6) NOT NULL,sent_at TIMESTAMP(6),next_attempt_at TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL);CREATE INDEX idx_notifications_tenant_created ON notifications(tenant_id,created_at);CREATE INDEX idx_notifications_status_attempt ON notifications(status,next_attempt_at);
